"""Async HTTP client for the Coval REST API."""

from __future__ import annotations

import asyncio
import json
import random
import time
from datetime import datetime, timezone
from email.utils import parsedate_to_datetime
from typing import Any, Dict, List, Optional

import aiohttp
import structlog

from rasa.builder.copilot.mcp_server.tools.coval.filters import coval_filter_equals

structlogger = structlog.get_logger()

COVAL_API_BASE_URL = "https://api.coval.dev/v1"
_TERMINAL_RUN_STATUSES = frozenset({"COMPLETED", "FAILED", "CANCELLED", "DELETED"})
_IDEMPOTENT_HTTP_METHODS = frozenset({"GET", "HEAD", "DELETE"})
_RETRY_MAX_ATTEMPTS = 5
_RETRY_BASE_DELAY_S = 0.2
_RETRY_MAX_DELAY_S = 10.0
_RETRY_AFTER_CAP_S = 60.0


class CovalApiError(Exception):
    """Raised when a Coval API request fails."""

    def __init__(
        self,
        message: str,
        *,
        status: Optional[int] = None,
        body: Optional[str] = None,
    ) -> None:
        detail = message
        if body:
            detail = f"{message}: {body}"
        super().__init__(detail)
        self.status = status
        self.body = body


def parse_retry_after_seconds(value: Optional[str]) -> Optional[float]:
    """Parse a ``Retry-After`` header as seconds to wait.

    Accepts integer/float seconds or an HTTP-date, matching Coval's TypeScript
    SDK. Returns ``None`` when the header is missing or unusable.
    """
    if value is None:
        return None
    stripped = value.strip()
    if not stripped:
        return None
    try:
        seconds = float(stripped)
    except ValueError:
        pass
    else:
        if seconds >= 0.0:
            return seconds
        return None
    try:
        retry_at = parsedate_to_datetime(stripped)
    except (TypeError, ValueError, IndexError, OverflowError):
        return None
    if retry_at.tzinfo is None:
        retry_at = retry_at.replace(tzinfo=timezone.utc)
    delay_s = (retry_at - datetime.now(timezone.utc)).total_seconds()
    return max(0.0, delay_s)


def retry_delay_s(attempt: int, retry_after: Optional[str]) -> float:
    """Seconds to sleep before the next attempt (1-based ``attempt`` just failed)."""
    retry_after_s = parse_retry_after_seconds(retry_after)
    if retry_after_s is not None:
        return min(retry_after_s, _RETRY_AFTER_CAP_S)
    exponential = _RETRY_BASE_DELAY_S * (2 ** (attempt - 1))
    capped = min(exponential, _RETRY_MAX_DELAY_S)
    jitter_s = random.uniform(0.0, capped * 0.25)
    return capped + jitter_s


def _is_retryable_http_status(method: str, status: int) -> bool:
    """Return whether an HTTP error status warrants another attempt.

    429 is retried on any method. 408 and 5xx are retried only on idempotent
    methods so mutating POST/PATCH calls are not duplicated when the server
    applied the write but the client saw a transient failure. Transport errors
    are handled separately in ``_request_with_retries``.
    """
    if status == 429:
        return True
    if method.upper() not in _IDEMPOTENT_HTTP_METHODS:
        return False
    if status == 408:
        return True
    return 500 <= status < 600


def _decode_json_object(body_text: str, *, method: str, path: str) -> Dict[str, Any]:
    if not body_text.strip():
        return {}
    try:
        payload = json.loads(body_text)
    except json.JSONDecodeError as error:
        raise CovalApiError(
            f"Coval API {method} {path} returned invalid JSON",
            body=body_text,
        ) from error
    if not isinstance(payload, dict):
        raise CovalApiError(
            f"Coval API {method} {path} returned a non-object JSON payload",
            body=body_text,
        )
    return payload


class CovalClient:
    """Minimal Coval client for launch/poll/fetch voice simulation runs."""

    def __init__(
        self,
        api_key: str,
        *,
        base_url: str = COVAL_API_BASE_URL,
        session: Optional[aiohttp.ClientSession] = None,
        owns_session: bool = False,
    ) -> None:
        self._api_key = api_key
        self._base_url = base_url.rstrip("/")
        self._session = session
        self._owns_session = owns_session

    async def __aenter__(self) -> CovalClient:
        if self._session is None:
            self._session = aiohttp.ClientSession()
            self._owns_session = True
        return self

    async def __aexit__(self, *args: object) -> None:
        if self._owns_session and self._session is not None:
            await self._session.close()
            self._session = None

    async def _request(
        self,
        method: str,
        path: str,
        *,
        json_body: Optional[Dict[str, Any]] = None,
        params: Optional[Dict[str, str]] = None,
        timeout_s: float = 60.0,
    ) -> Dict[str, Any]:
        url = f"{self._base_url}/{path.lstrip('/')}"
        headers = {
            "X-API-Key": self._api_key,
            "Content-Type": "application/json",
        }
        timeout = aiohttp.ClientTimeout(total=timeout_s)
        ephemeral_session = self._session is None
        session = self._session or aiohttp.ClientSession()
        try:
            return await self._request_with_retries(
                session,
                method=method,
                path=path,
                url=url,
                headers=headers,
                json_body=json_body,
                params=params,
                timeout=timeout,
            )
        finally:
            if ephemeral_session:
                await session.close()

    async def _request_with_retries(
        self,
        session: aiohttp.ClientSession,
        *,
        method: str,
        path: str,
        url: str,
        headers: Dict[str, str],
        json_body: Optional[Dict[str, Any]],
        params: Optional[Dict[str, str]],
        timeout: aiohttp.ClientTimeout,
    ) -> Dict[str, Any]:
        last_error: Optional[CovalApiError] = None
        for attempt in range(1, _RETRY_MAX_ATTEMPTS + 1):
            retry_after_header: Optional[str] = None
            status: Optional[int] = None
            try:
                async with session.request(
                    method,
                    url,
                    headers=headers,
                    json=json_body,
                    params=params,
                    timeout=timeout,
                ) as resp:
                    status = resp.status
                    retry_after_header = resp.headers.get("Retry-After")
                    body_text = await resp.text()
                    if status < 400:
                        return _decode_json_object(body_text, method=method, path=path)
                    last_error = CovalApiError(
                        f"Coval API {method} {path} failed with status {status}",
                        status=status,
                        body=body_text,
                    )
            except (aiohttp.ClientError, asyncio.TimeoutError) as error:
                last_error = CovalApiError(
                    f"Coval API {method} {path} failed with a transport error",
                    body=str(error),
                )
                if attempt >= _RETRY_MAX_ATTEMPTS:
                    raise last_error from error

            can_retry = attempt < _RETRY_MAX_ATTEMPTS and (
                status is None or _is_retryable_http_status(method, status)
            )
            if not can_retry:
                if last_error is None:
                    raise RuntimeError(
                        f"Coval API {method} {path} failed without an error"
                    )
                raise last_error

            delay_s = retry_delay_s(attempt, retry_after_header)
            structlogger.warning(
                "coval.api.retry",
                method=method,
                path=path,
                status=status,
                attempt=attempt,
                max_attempts=_RETRY_MAX_ATTEMPTS,
                delay_s=round(delay_s, 3),
            )
            await asyncio.sleep(delay_s)

        if last_error is None:
            raise RuntimeError(f"Coval API {method} {path} exhausted retries")
        raise last_error

    async def launch_run(self, payload: Dict[str, Any]) -> str:
        """Launch a Coval run and return the run id."""
        data = await self._request("POST", "runs", json_body=payload)
        run_id = data.get("run", {}).get("run_id")
        if not run_id:
            raise CovalApiError(
                "Coval launch response missing run.run_id",
                body=str(data),
            )
        return str(run_id)

    async def create_agent(self, payload: Dict[str, Any]) -> str:
        """Create a Coval agent and return its id."""
        data = await self._request("POST", "agents", json_body=payload)
        agent = data.get("agent")
        if not isinstance(agent, dict):
            raise CovalApiError(
                "Coval create_agent response missing agent object",
                body=str(data),
            )
        agent_id = agent.get("id")
        if not agent_id:
            raise CovalApiError(
                "Coval create_agent response missing agent.id",
                body=str(data),
            )
        return str(agent_id)

    async def list_agents(
        self,
        *,
        display_name: Optional[str] = None,
        page_size: int = 100,
    ) -> List[Dict[str, Any]]:
        """List agents, optionally filtered by exact ``display_name``."""
        agents: List[Dict[str, Any]] = []
        page_token: Optional[str] = None
        while True:
            params: Dict[str, str] = {"page_size": str(page_size)}
            if display_name:
                params["filter"] = coval_filter_equals("display_name", display_name)
            if page_token:
                params["page_token"] = page_token
            data = await self._request("GET", "agents", params=params)
            page_items = data.get("agents", [])
            if isinstance(page_items, list):
                agents.extend(item for item in page_items if isinstance(item, dict))
            page_token = data.get("next_page_token")
            if not page_token:
                break
        return agents

    async def create_test_set(self, payload: Dict[str, Any]) -> str:
        """Create a Coval test set and return its id."""
        data = await self._request("POST", "test-sets", json_body=payload)
        test_set = data.get("test_set")
        if not isinstance(test_set, dict):
            raise CovalApiError(
                "Coval create_test_set response missing test_set object",
                body=str(data),
            )
        test_set_id = test_set.get("id")
        if not test_set_id:
            raise CovalApiError(
                "Coval create_test_set response missing test_set.id",
                body=str(data),
            )
        return str(test_set_id)

    async def list_test_sets(
        self,
        *,
        display_name: Optional[str] = None,
        page_size: int = 100,
    ) -> List[Dict[str, Any]]:
        """List test sets, optionally filtered by exact ``display_name``."""
        test_sets: List[Dict[str, Any]] = []
        page_token: Optional[str] = None
        while True:
            params: Dict[str, str] = {"page_size": str(page_size)}
            if display_name:
                params["filter"] = coval_filter_equals("display_name", display_name)
            if page_token:
                params["page_token"] = page_token
            data = await self._request("GET", "test-sets", params=params)
            page_items = data.get("test_sets", [])
            if isinstance(page_items, list):
                test_sets.extend(item for item in page_items if isinstance(item, dict))
            page_token = data.get("next_page_token")
            if not page_token:
                break
        return test_sets

    async def delete_test_case(self, test_case_id: str) -> None:
        """Delete a Coval test case permanently."""
        await self._request("DELETE", f"test-cases/{test_case_id}")

    async def get_agent(self, agent_id: str) -> Dict[str, Any]:
        """Fetch a single agent resource."""
        data = await self._request("GET", f"agents/{agent_id}")
        agent = data.get("agent")
        if not isinstance(agent, dict):
            raise CovalApiError(
                f"Coval get_agent response missing agent object for {agent_id}",
                body=str(data),
            )
        return agent

    async def get_run(self, run_id: str) -> Dict[str, Any]:
        """Fetch a single run resource."""
        data = await self._request("GET", f"runs/{run_id}")
        run = data.get("run")
        if not isinstance(run, dict):
            raise CovalApiError(
                f"Coval get_run response missing run object for {run_id}",
                body=str(data),
            )
        return run

    async def wait_for_run(
        self,
        run_id: str,
        *,
        poll_interval_s: float = 30.0,
        max_wait_time_s: float = 1800.0,
    ) -> Dict[str, Any]:
        """Poll until the run reaches a terminal status or the timeout expires."""
        deadline = time.monotonic() + max_wait_time_s
        last_run: Dict[str, Any] = {}
        while time.monotonic() < deadline:
            last_run = await self.get_run(run_id)
            status = str(last_run.get("status", "")).upper()
            if status in _TERMINAL_RUN_STATUSES:
                return last_run
            await asyncio.sleep(poll_interval_s)
        raise CovalApiError(
            f"Coval run {run_id} did not finish within {max_wait_time_s}s; "
            f"last status={last_run.get('status')!r}",
        )

    async def list_simulations(
        self,
        run_id: str,
        *,
        page_size: int = 100,
    ) -> List[Dict[str, Any]]:
        """List all simulations for a run (paginated)."""
        simulations: List[Dict[str, Any]] = []
        page_token: Optional[str] = None
        while True:
            params: Dict[str, str] = {
                "filter": coval_filter_equals("run_id", run_id),
                "page_size": str(page_size),
            }
            if page_token:
                params["page_token"] = page_token
            data = await self._request("GET", "simulations", params=params)
            page_items = data.get("simulations", [])
            if isinstance(page_items, list):
                simulations.extend(
                    item for item in page_items if isinstance(item, dict)
                )
            page_token = data.get("next_page_token")
            if not page_token:
                break
        return simulations

    async def get_simulation(self, simulation_id: str) -> Dict[str, Any]:
        """Fetch a simulation including its transcript."""
        data = await self._request("GET", f"simulations/{simulation_id}")
        simulation = data.get("simulation")
        if not isinstance(simulation, dict):
            raise CovalApiError(
                f"Coval get_simulation response missing simulation for "
                f"{simulation_id}",
                body=str(data),
            )
        return simulation

    async def get_simulation_audio_url(self, simulation_id: str) -> Dict[str, Any]:
        """Return the presigned audio download payload for a simulation."""
        data = await self._request("GET", f"simulations/{simulation_id}/audio")
        audio_url = data.get("audio_url") or data.get("url")
        if not isinstance(audio_url, str) or not audio_url.strip():
            raise CovalApiError(
                f"Coval get_simulation_audio_url response missing audio URL for "
                f"{simulation_id}",
                body=str(data),
            )
        return data

    async def download_url_bytes(
        self,
        url: str,
        *,
        timeout_s: float = 120.0,
    ) -> tuple[bytes, Optional[str]]:
        """Download raw bytes from a URL (e.g. a Coval presigned audio link).

        Returns ``(body, content_type)``. Does not attach the Coval API key —
        presigned S3 URLs are self-authorizing.
        """
        timeout = aiohttp.ClientTimeout(total=timeout_s)
        ephemeral_session = self._session is None
        session = self._session or aiohttp.ClientSession()
        try:
            async with session.get(url, timeout=timeout) as resp:
                body = await resp.read()
                if resp.status >= 400:
                    raise CovalApiError(
                        f"Audio download failed with status {resp.status}",
                        status=resp.status,
                        body=body[:600].decode("utf-8", errors="replace"),
                    )
                content_type = resp.headers.get("Content-Type")
                return body, content_type
        finally:
            if ephemeral_session:
                await session.close()

    async def get_metric(self, metric_id: str) -> Dict[str, Any]:
        """Fetch a metric definition (display name, type, etc.)."""
        data = await self._request("GET", f"metrics/{metric_id}")
        metric = data.get("metric")
        if not isinstance(metric, dict):
            raise CovalApiError(
                f"Coval get_metric response missing metric for {metric_id}",
                body=str(data),
            )
        return metric

    async def list_simulation_metrics(
        self,
        simulation_id: str,
        *,
        page_size: int = 100,
    ) -> List[Dict[str, Any]]:
        """List metric outputs scored for a simulation (paginated)."""
        metrics: List[Dict[str, Any]] = []
        page_token: Optional[str] = None
        while True:
            params: Dict[str, str] = {
                "page_size": str(page_size),
                "order_by": "metric_name",
            }
            if page_token:
                params["page_token"] = page_token
            data = await self._request(
                "GET",
                f"simulations/{simulation_id}/metrics",
                params=params,
            )
            page_items = data.get("metrics", [])
            if isinstance(page_items, list):
                metrics.extend(item for item in page_items if isinstance(item, dict))
            page_token = data.get("next_page_token")
            if not page_token:
                break
        return metrics
